/**
 * Interactive viewer for coxeter shape tables.
 *
 * Every element of class `polyhedron-model` on the page contains a compact
 * JSON payload (vertices and face index lists) generated by the
 * polyhedron_table Sphinx extension at documentation build time. This module
 * renders each payload as an interactive 3D model.
 *
 * The key design constraint is that browsers only allow a handful of live
 * WebGL contexts per page, which is what previously forced the shape tables
 * to be split across many pages. Here, a single offscreen WebGL context
 * (shared by every model on the page) renders into one canvas at a time and
 * the result is copied into lightweight 2D canvases inside the table cells.
 * A page can therefore contain hundreds of models. Models are built and
 * rendered lazily as they approach the viewport (IntersectionObserver), so
 * only what is actually visible costs anything.
 */

/* three.js is loaded lazily from a CDN (the docs already rely on a CDN for
 * x3dom) and only on pages that actually contain models. Pin the version for
 * reproducible builds. */
const THREE_URL = "https://cdn.jsdelivr.net/npm/three@0.186.0/build/three.module.js";

const MODEL_SELECTOR = ".polyhedron-model";
const DATA_SELECTOR = "script.polyhedron-data";
const RENDER_SIZE = 256; // Edge length (px) of the shared offscreen render target.
const ROOT_MARGIN = "200px"; // Pre-render margin around the viewport.
const AUTOROTATE_SPEED = 0.35; // Radians per second.
const MAX_TILT = 1.35;

const state = {
  THREE: null,
  renderer: null,
  models: [],
  faceMaterial: null,
  edgeMaterial: null,
  running: false,
  lastTime: 0,
};

const reducedMotion =
  typeof matchMedia === "function" &&
  matchMedia("(prefers-reduced-motion: reduce)").matches;

function fail(holder, message) {
  holder.classList.add("polyhedron-failed");
  console.warn("coxeter viewer:", message);
}

function clamp(value, low, high) {
  return Math.min(Math.max(value, low), high);
}

/** Create the single shared offscreen renderer. */
function createRenderer(THREE) {
  const canvas = document.createElement("canvas");
  canvas.width = RENDER_SIZE;
  canvas.height = RENDER_SIZE;
  const renderer = new THREE.WebGLRenderer({
    canvas,
    alpha: true,
    antialias: true,
    // Required to reliably copy the drawing buffer into 2D canvases.
    preserveDrawingBuffer: true,
  });
  renderer.setClearColor(0x000000, 0);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(RENDER_SIZE, RENDER_SIZE, false);
  return renderer;
}

/** Extract the payload of a holder element and prepare its 2D canvas. */
function createModel(holder) {
  const dataElement = holder.querySelector(DATA_SELECTOR);
  let data = null;
  try {
    data = JSON.parse(dataElement.textContent);
  } catch (error) {
    fail(holder, `invalid model payload (${error})`);
    return null;
  }
  if (!data || !Array.isArray(data.v) || !Array.isArray(data.f)) {
    fail(holder, "model payload is missing vertices or faces");
    return null;
  }
  const canvas = document.createElement("canvas");
  canvas.className = "polyhedron-canvas";
  canvas.setAttribute("role", "img");
  canvas.setAttribute("aria-label", `Interactive 3D model of ${data.n ?? "a polyhedron"}`);
  const fallback = holder.querySelector(".polyhedron-fallback");
  if (fallback) {
    fallback.remove();
  }
  holder.appendChild(canvas);
  return {
    holder,
    canvas,
    context: canvas.getContext("2d"),
    data,
    built: false,
    visible: false,
    dirty: true,
    interacted: false,
    autoRotate: !reducedMotion,
    tilt: -0.35,
    spin: 0.6,
    vTilt: 0,
    vSpin: 0,
    scene: null,
    camera: null,
    group: null,
  };
}

/** Build three.js scene graph objects for a model (done lazily). */
function buildModel(model) {
  const { THREE } = state;
  const { v, f } = model.data;

  // Faces are polygons of any length; convex polyhedra can be fan
  // triangulated. Positions are duplicated per triangle so that computed
  // vertex normals are flat (faceted) shading.
  const positions = [];
  const edgePositions = [];
  const seenEdges = new Set();
  for (const face of f) {
    for (let i = 1; i + 1 < face.length; i++) {
      for (const k of [face[0], face[i], face[i + 1]]) {
        positions.push(v[k][0], v[k][1], v[k][2]);
      }
    }
    for (let i = 0; i < face.length; i++) {
      const a = face[i];
      const b = face[(i + 1) % face.length];
      const key = a < b ? `${a}_${b}` : `${b}_${a}`;
      if (!seenEdges.has(key)) {
        seenEdges.add(key);
        edgePositions.push(v[a][0], v[a][1], v[a][2], v[b][0], v[b][1], v[b][2]);
      }
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geometry.computeVertexNormals();
  geometry.computeBoundingSphere();
  const edges = new THREE.BufferGeometry();
  edges.setAttribute("position", new THREE.Float32BufferAttribute(edgePositions, 3));

  const group = new THREE.Group();
  group.add(new THREE.Mesh(geometry, state.faceMaterial));
  group.add(new THREE.LineSegments(edges, state.edgeMaterial));

  const scene = new THREE.Scene();
  const key = new THREE.DirectionalLight(0xffffff, 2.8);
  key.position.set(2.5, 3, 4);
  const fill = new THREE.DirectionalLight(0xffffff, 1.0);
  fill.position.set(-3, -1.5, -2);
  scene.add(group, key, fill, new THREE.AmbientLight(0xffffff, 1.2));

  // Frame the bounding sphere of the shape with a camera looking down a
  // pleasant diagonal, mirroring the viewpoint of the previous X3D models.
  const camera = new THREE.PerspectiveCamera(37.5, 1, 0.01, 100);
  const center = geometry.boundingSphere.center;
  const radius = Math.max(geometry.boundingSphere.radius, 1e-6);
  const distance = (1.1 * radius) / Math.sin((camera.fov * Math.PI) / 360);
  camera.position.set(1, 0.65, 1.4).normalize().multiplyScalar(distance).add(center);
  camera.lookAt(center);
  camera.near = distance / 100;
  camera.far = distance * 10;
  camera.updateProjectionMatrix();

  model.group = group;
  model.scene = scene;
  model.camera = camera;
  model.built = true;
}

/** Render one model into its 2D canvas via the shared WebGL context. */
function renderModel(model) {
  model.group.rotation.set(model.tilt, model.spin, 0);
  state.renderer.render(model.scene, model.camera);
  const { canvas, context } = model;
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.drawImage(state.renderer.domElement, 0, 0, canvas.width, canvas.height);
  model.dirty = false;
}

function tick(time) {
  const dt = Math.min((time - state.lastTime) / 1000, 0.05);
  state.lastTime = time;
  let active = false;
  for (const model of state.models) {
    if (!model.visible) {
      continue;
    }
    if (model.autoRotate) {
      model.spin += AUTOROTATE_SPEED * dt;
      model.dirty = true;
    } else if (!model.interacted && Math.abs(model.vSpin) + Math.abs(model.vTilt) > 1e-4) {
      model.spin += model.vSpin;
      model.tilt = clamp(model.tilt + model.vTilt, -MAX_TILT, MAX_TILT);
      model.vSpin *= 0.9;
      model.vTilt *= 0.9;
      model.dirty = true;
    }
    if (model.dirty) {
      renderModel(model);
    }
    active = true;
  }
  // Stop the loop entirely while no model is on screen.
  if (active) {
    requestAnimationFrame(tick);
  } else {
    state.running = false;
  }
}

function ensureRunning() {
  if (!state.running) {
    state.running = true;
    state.lastTime = performance.now();
    requestAnimationFrame(tick);
  }
}

function sizeCanvas(model) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const width = Math.max(1, Math.round(model.holder.clientWidth * dpr));
  model.canvas.width = width;
  model.canvas.height = width;
  model.dirty = true;
}

function addInteraction(model) {
  const element = model.canvas;
  let dragging = false;
  let lastX = 0;
  let lastY = 0;
  element.addEventListener("pointerdown", (event) => {
    dragging = true;
    lastX = event.clientX;
    lastY = event.clientY;
    model.interacted = true;
    model.autoRotate = false;
    element.setPointerCapture(event.pointerId);
    event.preventDefault();
  });
  element.addEventListener("pointermove", (event) => {
    if (!dragging) {
      return;
    }
    const dx = event.clientX - lastX;
    const dy = event.clientY - lastY;
    lastX = event.clientX;
    lastY = event.clientY;
    model.spin += dx * 0.01;
    model.tilt = clamp(model.tilt + dy * 0.01, -MAX_TILT, MAX_TILT);
    model.vSpin = dx * 0.01;
    model.vTilt = dy * 0.01;
    model.dirty = true;
    ensureRunning();
  });
  const release = () => {
    dragging = false;
  };
  element.addEventListener("pointerup", release);
  element.addEventListener("pointercancel", release);
}

async function boot() {
  const holders = Array.from(document.querySelectorAll(MODEL_SELECTOR));
  if (holders.length === 0) {
    return;
  }
  try {
    state.THREE = await import(THREE_URL);
  } catch (error) {
    holders.forEach((holder) => fail(holder, `cannot load three.js (${error})`));
    return;
  }
  const { THREE } = state;
  try {
    state.renderer = createRenderer(THREE);
  } catch (error) {
    holders.forEach((holder) => fail(holder, `WebGL unavailable (${error})`));
    return;
  }
  state.faceMaterial = new THREE.MeshLambertMaterial({
    color: 0x6495ed, // Cornflower blue, matching the previous X3D models.
    side: THREE.DoubleSide,
  });
  state.edgeMaterial = new THREE.LineBasicMaterial({ color: 0x1a1a2e });

  state.models = holders.map(createModel).filter(Boolean);
  if (state.models.length === 0) {
    return;
  }

  const intersectionObserver = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        const model = entry.target.__coxeterModel;
        model.visible = entry.isIntersecting;
        if (model.visible) {
          if (!model.built) {
            buildModel(model);
          }
          ensureRunning();
        }
      }
    },
    { rootMargin: ROOT_MARGIN },
  );

  const resizeObserver = new ResizeObserver((entries) => {
    for (const entry of entries) {
      const model = entry.target.__coxeterModel;
      sizeCanvas(model);
      if (model.visible) {
        ensureRunning();
      }
    }
  });

  for (const model of state.models) {
    model.holder.__coxeterModel = model;
    intersectionObserver.observe(model.holder);
    resizeObserver.observe(model.holder);
    addInteraction(model);
    sizeCanvas(model);
  }
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot);
} else {
  boot();
}
